use std::iter::Sum;

#[derive(Debug, Clone, Copy, PartialEq)]
struct Meters(f64);

impl Sum for Meters {
    fn sum<I: Iterator<Item = Meters>>(iter: I) -> Meters {
        Meters(iter.map(|m| m.0).sum())
    }
}

impl<'a> Sum<&'a Meters> for Meters {
    fn sum<I: Iterator<Item = &'a Meters>>(iter: I) -> Meters {
        Meters(iter.map(|m| m.0).sum())
    }
}

#[derive(Debug, PartialEq)]
struct Stats {
    count: usize,
    mean: f64,
    max: f64,
}

impl FromIterator<f64> for Stats {
    fn from_iter<I: IntoIterator<Item = f64>>(iter: I) -> Self {
        let (mut count, mut total, mut max) = (0usize, 0.0, f64::NEG_INFINITY);
        for x in iter {
            count += 1;
            total += x;
            max = max.max(x);
        }
        Stats { count, mean: if count == 0 { 0.0 } else { total / count as f64 }, max }
    }
}

unitTests:
test("sum by value and by reference", || {
    let v = vec![Meters(1.5), Meters(2.0), Meters(0.5)];
    check_eq(v.iter().sum::<Meters>(), Meters(4.0));
    check_eq(v.into_iter().sum::<Meters>(), Meters(4.0));
    check_eq(Vec::<Meters>::new().into_iter().sum::<Meters>(), Meters(0.0));
});

test("collect into stats", || {
    let s: Stats = [2.0, 4.0, 9.0].into_iter().collect();
    check_eq(s, Stats { count: 3, mean: 5.0, max: 9.0 });
    let lens: Stats = ["a", "abc", "ab"].iter().map(|w| w.len() as f64).collect();
    check_eq(lens.max, 3.0);
});

test("no items", || {
    let s: Stats = std::iter::empty::<f64>().collect();
    check_eq(s.count, 0);
    check_eq(s.mean, 0.0);
    check(s.max == f64::NEG_INFINITY);
});

